const lruPolicy = { pick: (keys) => keys[0] };
const fifoPolicy = { pick: (keys) => keys[keys.length - 1] };

class Cache {
  constructor(policy = lruPolicy) { this.policy = policy; this.items = new Map(); }
  victim(keys) { return this.policy.pick(keys); }
}

const cache = new Cache(fifoPolicy);   // policy chosen when the host is built
